// The store was declared on HalEngineConfig and reached the transport, but never the orchestrator.
describe('createHalEngine session store forwarding', () => {
  it('forwards the session store, so its write signal reaches the orchestrator', async () => {
    const saved: string[] = [];
    const session = recordingSessionStore(written => void saved.push(written.sessionId));
    const engine = createHalEngine({...base, session});

    await engine.orchestrator.processMessage(session.create('s1', 'u1') as ChatSession);

    expect(saved).toEqual(['s1']);
  });
});

describe('createHalEngine beforeSession failure lifecycle', () => {
  it('runs onError then afterSession when a config-installed beforeSession throws, leaving session entries untouched', async () => {
    const order: string[] = [];
    let entriesDuringCleanup = -1;
    const engine = createHalEngine({
      ...base,
      orchestrator: {
        hooks: {
          beforeSession: async () => {
            order.push('beforeSession');
            throw new Error('setup failed');
          },
          beforeUserInput: async (_session, message) => {
            order.push('beforeUserInput');
            return message;
          },
          beforeModelResponse: async (_session, systemPrompt) => {
            order.push('beforeModelResponse');
            return systemPrompt;
          },
          afterModelResponse: async () => void order.push('afterModelResponse'),
          onError: async (_session, error) => void order.push(`onError:${error.message}`),
          afterSession: async current => {
            entriesDuringCleanup = current.entries.length;
            order.push('afterSession');
          },
        },
      },
    });
    const session: ChatSession = {
      sessionId: 's-before-err',
      userId: 'u1',
      entries: [{role: 'user', content: 'hello', timestamp: ''}],
    };

    const rejection = await engine.orchestrator
      .processMessage(session)
      .then(() => 'resolved')
      .catch((caught: Error) => caught.message);

    expect({rejection, order, entriesDuringCleanup}).toEqual({
      rejection: 'setup failed',
      order: ['beforeSession', 'onError:setup failed', 'afterSession'],
      entriesDuringCleanup: 1,
    });
  });
});

